import { useCallback, useEffect, useState } from 'react';
import './index.css';
import { DIFFICULTIES, Difficulty, DifficultyId } from './game/config';
import type { EndResult } from './game/engine';
import { sfx } from './game/audio';
import Menu from './components/Menu';
import GameView from './components/GameView';
import { GameOver } from './components/Overlays';
type Screen = 'menu' | 'playing' | 'over';
export type Records = Record<DifficultyId, number>;
const KEY = 'torre-defensa:records';
function loadRecords(): Records {
  try {
    const r = JSON.parse(localStorage.getItem(KEY) || '{}');
    return { facil: r.facil || 0, normal: r.normal || 0, dificil: r.dificil || 0 };
  } catch { return { facil: 0, normal: 0, dificil: 0 }; }
}
export default function App() {
  const [screen, setScreen] = useState<Screen>('menu');
  const [diff, setDiff] = useState<Difficulty>(DIFFICULTIES[1]);
  const [records, setRecords] = useState<Records>(loadRecords);
  const [result, setResult] = useState<EndResult | null>(null);
  const [newRecord, setNewRecord] = useState(false);
  const [runId, setRunId] = useState(0);
  const [muted, setMuted] = useState(false);
  useEffect(() => () => sfx.stopMusic(), []);
  const start = useCallback((d: Difficulty) => {
    sfx.ensure(); sfx.click(); sfx.startMusic();
    setDiff(d); setResult(null); setRunId(n => n + 1); setScreen('playing');
  }, []);
  const toggleMute = useCallback(() => {
    setMuted(m => { sfx.setMuted(!m); return !m; });
  }, []);
  const onEnd = useCallback((r: EndResult) => {
    setResult(r);
    setRecords(prev => {
      const isNew = r.score > prev[diff.id];
      setNewRecord(isNew);
      if (!isNew) return prev;
      const next = { ...prev, [diff.id]: r.score };
      try { localStorage.setItem(KEY, JSON.stringify(next)); } catch { /* sin almacenamiento */ }
      return next;
    });
    sfx.stopMusic();
    setScreen('over');
  }, [diff.id]);
  const toMenu = useCallback(() => { sfx.stopMusic(); setScreen('menu'); }, []);
  return (
    <div className="td-root relative w-full h-full min-h-[100vh] overflow-hidden bg-[#0b0820] text-white select-none" style={{ height: '100vh' }}>
      {screen === 'menu' && (
        <Menu records={records} initial={diff.id} onPlay={start} muted={muted} onToggleMute={toggleMute} />
      )}
      {screen !== 'menu' && (
        <GameView key={runId} difficulty={diff} onEnd={onEnd} onRestart={() => start(diff)} onMenu={toMenu}
          muted={muted} onToggleMute={toggleMute} frozen={screen === 'over'} />
      )}
      {screen === 'over' && result && (
        <GameOver result={result} difficulty={diff} record={records[diff.id]} isNewRecord={newRecord}
          onRetry={() => start(diff)} onMenu={toMenu} />
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Game, Snapshot, EndResult } from '../game/engine';
import type { Difficulty, TowerKind } from '../game/config';
import HUD from './HUD';
import { PauseMenu } from './Overlays';
interface Props {
  difficulty: Difficulty;
  onEnd(r: EndResult): void;
  onRestart(): void;
  onMenu(): void;
  muted: boolean;
  onToggleMute(): void;
  frozen: boolean;
}
export default function GameView({ difficulty, onEnd, onRestart, onMenu, muted, onToggleMute, frozen }: Props) {
  const hostRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [snap, setSnap] = useState<Snapshot | null>(null);
  const [paused, setPaused] = useState(false);
  const endRef = useRef(onEnd);
  endRef.current = onEnd;
  useEffect(() => {
    if (!hostRef.current) return;
    const g = new Game(hostRef.current, difficulty, {
      onState: s => setSnap(s),
      onEnd: r => endRef.current(r),
      onPauseRequest: () => setPaused(p => !p),
    });
    gameRef.current = g;
    return () => { g.dispose(); gameRef.current = null; };
  }, [difficulty]);
  useEffect(() => { gameRef.current?.setPaused(paused || frozen); }, [paused, frozen]);
  const g = gameRef.current;
  return (
    <div className="absolute inset-0">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="absolute inset-0 pointer-events-none" style={{ background: 'radial-gradient(ellipse at center, transparent 55%, rgba(7,4,24,0.55) 100%)' }} />
      {snap && !frozen && (
        <HUD
          s={snap} muted={muted}
          onBuild={(k: TowerKind) => g?.selectBuild(k)}
          onUpgrade={() => g?.upgradeSelected()}
          onSell={() => g?.sellSelected()}
          onNextWave={() => g?.callNextWave()}
          onSpeed={() => g?.toggleSpeed()}
          onPause={() => setPaused(true)}
          onToggleMute={onToggleMute}
        />
      )}
      {paused && !frozen && (
        <PauseMenu onResume={() => setPaused(false)} onRestart={onRestart} onMenu={onMenu} muted={muted} onToggleMute={onToggleMute} />
      )}
    </div>
  );
}

import { Heart, Coins, Flag, Star, Pause, FastForward, SkipForward, Volume2, VolumeX, Bomb, Zap, Snowflake, Rocket, ArrowUpCircle, Trash2, Swords } from 'lucide-react';
import type { ReactNode } from 'react';
import clsx from 'clsx';
import { TOWERS, TOWER_ORDER, TowerKind } from '../game/config';
import type { Snapshot } from '../game/engine';
const ICONS = { cannon: Bomb, laser: Zap, ice: Snowflake, missile: Rocket };
interface Props {
  s: Snapshot;
  muted: boolean;
  onBuild(k: TowerKind): void;
  onUpgrade(): void;
  onSell(): void;
  onNextWave(): void;
  onSpeed(): void;
  onPause(): void;
  onToggleMute(): void;
}
function Stat({ icon, value, label, tone }: { icon: ReactNode; value: ReactNode; label: string; tone: string }) {
  return (
    <div className="td-glass rounded-xl px-2.5 sm:px-3 py-1.5 flex items-center gap-2 min-w-0">
      <span className={tone}>{icon}</span>
      <div className="leading-none">
        <div className="text-[9px] sm:text-[10px] uppercase tracking-wider text-violet-200/60">{label}</div>
        <div className="font-black text-sm sm:text-lg tabular-nums">{value}</div>
      </div>
    </div>
  );
}
function IconBtn({ onClick, children, active, label }: { onClick(): void; children: ReactNode; active?: boolean; label: string }) {
  return (
    <button onClick={onClick} aria-label={label} title={label}
      className={clsx('td-glass rounded-xl w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center hover:bg-white/15 active:scale-95 transition',
        active && 'bg-amber-400/30 border-amber-300/60 text-amber-200')}>
      {children}
    </button>
  );
}
export default function HUD({ s, muted, onBuild, onUpgrade, onSell, onNextWave, onSpeed, onPause, onToggleMute }: Props) {
  const livesPct = s.lives / s.maxLives;
  const sel = s.selected;
  return (
    <div className="absolute inset-0 pointer-events-none text-white">
      {/* Barra superior */}
      <div className="absolute top-2 left-2 right-2 flex items-start justify-between gap-2">
        <div className="flex flex-wrap gap-1.5 sm:gap-2 pointer-events-auto">
          <Stat label="Vidas" tone={livesPct < 0.3 ? 'text-rose-400 animate-pulse' : 'text-rose-400'} icon={<Heart size={18} className="fill-current" />} value={s.lives} />
          <Stat label="Oro" tone="text-amber-300" icon={<Coins size={18} />} value={s.gold} />
          <Stat label="Oleada" tone="text-cyan-300" icon={<Flag size={18} />} value={<>{s.wave}<span className="text-violet-300/60 text-xs">/{s.totalWaves}</span></>} />
          <Stat label="Puntos" tone="text-pink-300" icon={<Star size={18} />} value={s.score.toLocaleString('es')} />
        </div>
        <div className="flex gap-1.5 pointer-events-auto">
          <IconBtn label="Velocidad x2 (F)" onClick={onSpeed} active={s.speed > 1}>
            <span className="flex items-center text-xs font-black"><FastForward size={16} />{s.speed > 1 ? 'x2' : ''}</span>
          </IconBtn>
          <IconBtn label={muted ? 'Activar sonido' : 'Silenciar'} onClick={onToggleMute}>{muted ? <VolumeX size={18} /> : <Volume2 size={18} />}</IconBtn>
          <IconBtn label="Pausa (Esc)" onClick={onPause}><Pause size={18} /></IconBtn>
        </div>
      </div>
      {/* Estado de oleada */}
      <div className="absolute top-[60px] sm:top-16 left-1/2 -translate-x-1/2 flex flex-col items-center gap-1.5">
        {s.toast && <div className="rounded-full px-3 py-1 text-xs font-bold bg-rose-600/90 shadow">{s.toast}</div>}
        {s.bannerT > 0 && (
          <div key={s.banner} className="td-banner text-2xl sm:text-4xl font-black text-amber-200 whitespace-nowrap">{s.banner}</div>
        )}
        {!s.waveActive && s.countdown > 0 && s.wave < s.totalWaves && (
          <div className="td-glass rounded-full px-4 py-1 text-sm text-violet-100">
            Siguiente oleada en <b className="text-amber-300 tabular-nums">{Math.ceil(s.countdown)}</b> s
          </div>
        )}
        {s.waveActive && (
          <div className="td-glass rounded-full px-3 py-0.5 text-xs text-violet-100 flex items-center gap-1.5">
            <Swords size={13} className="text-rose-300" /> Enemigos restantes: <b className="tabular-nums">{s.enemiesLeft}</b>
          </div>
        )}
      </div>
      {/* Panel de torre seleccionada */}
      {sel && (
        <div className="absolute right-2 top-[64px] sm:top-16 td-glass rounded-2xl p-3 w-56 pointer-events-auto">
          <div className="flex items-center gap-2">
            <div className="w-9 h-9 rounded-xl flex items-center justify-center" style={{ background: TOWERS[sel.kind].color + '33', color: TOWERS[sel.kind].color }}>
              {(() => { const I = ICONS[sel.kind]; return <I size={20} />; })()}
            </div>
            <div>
              <div className="font-black leading-none">{sel.name}</div>
              <div className="text-amber-300 text-xs mt-0.5">{'★'.repeat(sel.level)}<span className="text-white/25">{'★'.repeat(3 - sel.level)}</span> Nivel {sel.level}</div>
            </div>
          </div>
          <div className="mt-2 text-xs text-violet-100/80 grid grid-cols-2 gap-1">
            <div>Daño: <b className="text-white">{sel.dmg}{sel.kind === 'laser' ? '/s' : ''}</b>{sel.nextDmg !== null && <span className="text-lime-300"> → {sel.nextDmg}</span>}</div>
            <div>Alcance: <b className="text-white">{sel.range.toFixed(1)}</b></div>
          </div>
          <div className="mt-2.5 grid grid-cols-2 gap-1.5">
            <button onClick={onUpgrade} disabled={sel.maxed || (sel.upgradeCost ?? 0) > s.gold}
              className="rounded-xl py-2 text-xs font-black bg-gradient-to-r from-lime-400 to-emerald-500 disabled:from-slate-600 disabled:to-slate-700 disabled:text-white/50 flex flex-col items-center leading-tight">
              <span className="flex items-center gap-1"><ArrowUpCircle size={14} /> Mejorar</span>
              <span className="text-[10px] font-bold">{sel.maxed ? 'Máximo' : `${sel.upgradeCost} oro (U)`}</span>
            </button>
            <button onClick={onSell} className="rounded-xl py-2 text-xs font-black bg-gradient-to-r from-rose-500 to-red-600 flex flex-col items-center leading-tight">
              <span className="flex items-center gap-1"><Trash2 size={14} /> Vender</span>
              <span className="text-[10px] font-bold">+{sel.sellValue} oro (X)</span>
            </button>
          </div>
        </div>
      )}
      {/* Barra de construcción */}
      <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex items-end gap-1.5 sm:gap-2 pointer-events-auto">
        {TOWER_ORDER.map((k, i) => {
          const t = TOWERS[k]; const Icon = ICONS[k];
          const cost = t.levels[0].cost; const afford = s.gold >= cost; const on = s.buildKind === k;
          return (
            <button key={k} onClick={() => onBuild(k)}
              className={clsx('td-glass relative rounded-2xl w-[68px] sm:w-[84px] pt-2 pb-1.5 flex flex-col items-center transition active:scale-95',
                on ? 'ring-2 ring-amber-300 -translate-y-1.5 bg-white/10' : 'hover:bg-white/10', !afford && 'opacity-50')}>
              <span className="absolute top-1 left-1.5 text-[10px] text-violet-200/60 font-bold">{i + 1}</span>
              <div className="w-9 h-9 rounded-xl flex items-center justify-center" style={{ background: t.color + '33', color: t.color }}><Icon size={20} /></div>
              <div className="text-[11px] font-bold mt-1">{t.short}</div>
              <div className={clsx('text-[11px] font-black flex items-center gap-0.5', afford ? 'text-amber-300' : 'text-rose-300')}><Coins size={10} />{cost}</div>
            </button>
          );
        })}
        <button onClick={onNextWave} disabled={!s.canCallWave}
          className="rounded-2xl w-[68px] sm:w-[84px] h-[84px] sm:h-[88px] flex flex-col items-center justify-center bg-gradient-to-b from-rose-500 to-fuchsia-700 font-black text-[11px] shadow-lg disabled:opacity-40 active:scale-95">
          <SkipForward size={22} />
          <span className="mt-1 leading-tight text-center">Oleada<br />(N)</span>
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Castle, Trophy, Play, Volume2, VolumeX, Bomb, Zap, Snowflake, Rocket, Skull, Keyboard, Hand } from 'lucide-react';
import clsx from 'clsx';
import { DIFFICULTIES, Difficulty, DifficultyId, TOWERS, TOWER_ORDER } from '../game/config';
import type { Records } from '../App';
const TOWER_ICONS = { cannon: Bomb, laser: Zap, ice: Snowflake, missile: Rocket };
interface Props {
  records: Records;
  initial: DifficultyId;
  onPlay(d: Difficulty): void;
  muted: boolean;
  onToggleMute(): void;
}
export default function Menu({ records, initial, onPlay, muted, onToggleMute }: Props) {
  const [sel, setSel] = useState<DifficultyId>(initial);
  const diff = DIFFICULTIES.find(d => d.id === sel)!;
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.code === 'Enter') onPlay(diff); };
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, [diff, onPlay]);
  return (
    <div className="td-menu-bg absolute inset-0 overflow-y-auto">
      <button onClick={onToggleMute} className="absolute top-4 right-4 z-10 td-glass rounded-full p-2.5 hover:bg-white/10" aria-label="Silencio">
        {muted ? <VolumeX size={20} /> : <Volume2 size={20} />}
      </button>
      <div className="min-h-full flex flex-col items-center justify-center px-5 py-10">
        <div className="td-float mb-3 flex items-center justify-center w-20 h-20 rounded-3xl bg-gradient-to-br from-amber-300 via-pink-400 to-violet-600 shadow-[0_0_60px_rgba(244,114,182,0.6)]">
          <Castle size={44} className="text-white drop-shadow" />
        </div>
        <h1 className="td-title text-5xl sm:text-7xl font-black text-center leading-none">TORRE DEFENSA</h1>
        <p className="mt-3 max-w-xl text-center text-violet-100/85 text-sm sm:text-base">
          Hordas de criaturas cruzan el portal hacia el <b className="text-cyan-300">Núcleo de cristal</b>. Construye y mejora torres
          a lo largo del camino y resiste <b className="text-amber-300">20 oleadas</b> con jefes colosales.
        </p>
        <div className="mt-6 grid grid-cols-2 sm:grid-cols-4 gap-2.5 w-full max-w-2xl">
          {TOWER_ORDER.map(k => {
            const t = TOWERS[k]; const Icon = TOWER_ICONS[k];
            return (
              <div key={k} className="td-glass rounded-2xl p-3 flex flex-col items-center text-center">
                <div className="w-10 h-10 rounded-xl flex items-center justify-center mb-1.5" style={{ background: t.color + '33', color: t.color }}>
                  <Icon size={22} />
                </div>
                <div className="font-bold text-sm">{t.name}</div>
                <div className="text-[11px] text-violet-200/70 leading-tight mt-0.5">{t.desc}</div>
                <div className="text-amber-300 text-xs font-bold mt-1">{t.levels[0].cost} oro</div>
              </div>
            );
          })}
        </div>
        <div className="mt-6 td-glass rounded-2xl p-1.5 flex gap-1.5">
          {DIFFICULTIES.map(d => (
            <button key={d.id} onClick={() => setSel(d.id)}
              className={clsx('px-4 sm:px-6 py-2 rounded-xl text-sm font-bold transition-all',
                sel === d.id ? 'bg-gradient-to-r from-amber-400 to-pink-500 text-white shadow-lg' : 'text-violet-200 hover:bg-white/10')}>
              {d.name}
            </button>
          ))}
        </div>
        <div className="mt-2 text-xs text-violet-200/70">
          {diff.lives} vidas · {diff.gold} de oro inicial · enemigos x{diff.hpMul.toFixed(2)} de vida
        </div>
        <div className="mt-2 flex items-center gap-2 text-amber-200 text-sm">
          <Trophy size={16} /> Récord ({diff.name}): <b>{records[sel].toLocaleString('es')}</b>
        </div>
        <button onClick={() => onPlay(diff)}
          className="mt-6 group flex items-center gap-3 px-12 py-4 rounded-2xl text-xl font-black bg-gradient-to-r from-amber-400 via-orange-500 to-pink-500 shadow-[0_10px_40px_rgba(249,115,22,0.5)] hover:scale-105 active:scale-95 transition-transform">
          <Play size={24} className="fill-white" /> Jugar
        </button>
        <div className="mt-7 grid sm:grid-cols-2 gap-3 max-w-2xl w-full text-xs text-violet-100/80">
          <div className="td-glass rounded-2xl p-3">
            <div className="flex items-center gap-2 font-bold text-white mb-1"><Keyboard size={15} /> Teclado y ratón</div>
            Clic en una casilla para construir o seleccionar · Flechas/WASD mueven el cursor · 1-4 elige torre ·
            Espacio construye/mejora · U mejora · X vende · N siguiente oleada · F velocidad x2 · Esc/P pausa
          </div>
          <div className="td-glass rounded-2xl p-3">
            <div className="flex items-center gap-2 font-bold text-white mb-1"><Hand size={15} /> Táctil</div>
            Toca una torre de la barra inferior y luego una casilla de hierba. Toca una torre construida para mejorarla o venderla.
            <div className="flex items-center gap-1.5 mt-1.5 text-rose-300"><Skull size={13} /> Jefes en las oleadas 5, 10, 15 y 20.</div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect } from 'react';
import { Play, RotateCcw, Home, Volume2, VolumeX, Trophy, Skull, Crown, Flag, Swords, Heart, Sparkles } from 'lucide-react';
import confetti from 'canvas-confetti';
import type { EndResult } from '../game/engine';
import type { Difficulty } from '../game/config';
interface PauseProps { onResume(): void; onRestart(): void; onMenu(): void; muted: boolean; onToggleMute(): void; }
export function PauseMenu({ onResume, onRestart, onMenu, muted, onToggleMute }: PauseProps) {
  return (
    <div className="absolute inset-0 bg-[#070a24]/70 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="td-glass rounded-3xl p-6 w-full max-w-xs flex flex-col gap-2.5 shadow-2xl">
        <h2 className="td-title text-4xl font-black text-center mb-2">Pausa</h2>
        <button onClick={onResume} className="flex items-center justify-center gap-2 py-3 rounded-2xl font-black bg-gradient-to-r from-amber-400 to-pink-500 active:scale-95">
          <Play size={18} className="fill-white" /> Continuar
        </button>
        <button onClick={onRestart} className="flex items-center justify-center gap-2 py-3 rounded-2xl font-bold bg-white/10 hover:bg-white/20 active:scale-95">
          <RotateCcw size={18} /> Reiniciar
        </button>
        <button onClick={onToggleMute} className="flex items-center justify-center gap-2 py-3 rounded-2xl font-bold bg-white/10 hover:bg-white/20 active:scale-95">
          {muted ? <VolumeX size={18} /> : <Volume2 size={18} />} {muted ? 'Activar sonido' : 'Silenciar'}
        </button>
        <button onClick={onMenu} className="flex items-center justify-center gap-2 py-3 rounded-2xl font-bold bg-white/10 hover:bg-white/20 active:scale-95">
          <Home size={18} /> Menú principal
        </button>
        <p className="text-center text-xs text-violet-200/60 mt-1">Pulsa Esc o P para continuar</p>
      </div>
    </div>
  );
}
interface OverProps {
  result: EndResult; difficulty: Difficulty; record: number; isNewRecord: boolean;
  onRetry(): void; onMenu(): void;
}
export function GameOver({ result, difficulty, record, isNewRecord, onRetry, onMenu }: OverProps) {
  useEffect(() => {
    if (result.win || isNewRecord) {
      const fire = (x: number) => confetti({ particleCount: 90, spread: 70, origin: { x, y: 0.6 }, colors: ['#fbbf24', '#f472b6', '#67e8f9', '#a3e635'] });
      fire(0.25); setTimeout(() => fire(0.75), 250);
    }
    const k = (e: KeyboardEvent) => { if (e.code === 'Enter' || e.code === 'Space') onRetry(); };
    const id = setTimeout(() => window.addEventListener('keydown', k), 600);
    return () => { clearTimeout(id); window.removeEventListener('keydown', k); };
  }, [result, isNewRecord, onRetry]);
  const rows = [
    { icon: <Flag size={16} />, label: 'Oleada alcanzada', value: `${result.wave} / 20` },
    { icon: <Swords size={16} />, label: 'Enemigos derrotados', value: result.kills },
    { icon: <Heart size={16} />, label: 'Vidas restantes', value: result.lives },
    { icon: <Trophy size={16} />, label: `Récord (${difficulty.name})`, value: record.toLocaleString('es') },
  ];
  return (
    <div className="absolute inset-0 bg-[#070a24]/75 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="td-glass rounded-3xl p-6 sm:p-8 w-full max-w-sm text-center shadow-2xl">
        <div className={`mx-auto w-16 h-16 rounded-2xl flex items-center justify-center mb-3 ${result.win ? 'bg-gradient-to-br from-amber-300 to-pink-500' : 'bg-gradient-to-br from-rose-500 to-violet-800'}`}>
          {result.win ? <Crown size={34} /> : <Skull size={34} />}
        </div>
        <h2 className="td-title text-4xl sm:text-5xl font-black">{result.win ? '¡Victoria!' : 'Núcleo destruido'}</h2>
        <p className="text-violet-200/80 text-sm mt-1">
          {result.win ? 'Has resistido las 20 oleadas. El reino está a salvo.' : 'Las hordas han roto tus defensas.'}
        </p>
        <div className="mt-5 text-xs uppercase tracking-widest text-violet-200/60">Puntuación</div>
        <div className="text-5xl font-black tabular-nums text-amber-200">{result.score.toLocaleString('es')}</div>
        {isNewRecord && (
          <div className="mt-2 inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-amber-400/20 text-amber-200 text-sm font-bold animate-pulse">
            <Sparkles size={14} /> ¡Nuevo récord!
          </div>
        )}
        <div className="mt-5 grid gap-1.5 text-sm">
          {rows.map(r => (
            <div key={r.label} className="flex items-center justify-between bg-white/5 rounded-xl px-3 py-2">
              <span className="flex items-center gap-2 text-violet-200/80">{r.icon}{r.label}</span>
              <b className="tabular-nums">{r.value}</b>
            </div>
