    cs.scale.setScalar(26 + rand() * 30);
    scene.add(cs);
  }
  // Rocas flotantes de fondo
  const floatRocks: THREE.Mesh[] = [];
  for (let i = 0; i < 9; i++) {
    const fr = new THREE.Mesh(rockGeo, rockMat);
    const a = (i / 9) * Math.PI * 2;
    fr.position.set(Math.cos(a) * (32 + rand() * 10), -4 + rand() * 8, Math.sin(a) * (24 + rand() * 8) - 6);
    const s = 1.5 + rand() * 2.5; fr.scale.set(s, s * 0.7, s);
    scene.add(fr); floatRocks.push(fr);
  }
  return {
    blocked, isPath, pathPts, cum, totalLen, corePos, portalPos, core, sample,
    update(t: number, coreHit: number) {
      ring.rotation.x = t * 0.8;
      vortex.rotation.z = -t * 2; vortexMat.opacity = 0.35 + Math.sin(t * 3) * 0.12;
      gem.rotation.y = t * 0.9; gem.position.y = 2.3 + Math.sin(t * 1.7) * 0.18;
      gemMat.emissive.setRGB(0.03 + coreHit * 0.9, 0.55 - coreHit * 0.4, 0.7 - coreHit * 0.5);
      halo.material.opacity = 0.65 + Math.sin(t * 2.3) * 0.15 + coreHit * 0.3;
      runeMat.opacity = 0.35 + Math.sin(t * 2) * 0.15;
      edgeMat.opacity = 0.4 + Math.sin(t * 1.3) * 0.15;
      floatRocks.forEach((r, i) => { r.position.y += Math.sin(t * 0.6 + i) * 0.004; r.rotation.y += 0.002; });
      stars.rotation.y = t * 0.004;
    },
    dispose() { disposables.forEach(d => d.dispose()); },
  };
}

