];
export interface Spawn { kind: EnemyKind; at: number }
/** Genera la lista de apariciones de la oleada w (1..20). */
export function buildWave(w: number): Spawn[] {
  const list: Spawn[] = [];
  let t = 0;
  const push = (kind: EnemyKind, n: number, gap: number) => {
    for (let i = 0; i < n; i++) { list.push({ kind, at: t }); t += gap; }
    t += 1.2;
  };
  const base = 7 + Math.floor(w * 1.3);
  push('grunt', base, Math.max(0.42, 0.7 - w * 0.015));
  push('runner', Math.floor(2 + w * 0.8), 0.4);
  if (w >= 3) push('tank', Math.floor(1 + w / 3), 1.4);
  push('flyer', Math.floor(1 + w / 2), 0.7);
  if (w >= 6) push('healer', Math.floor(1 + w / 4), 1.6);
  if (w >= 8 && w % 2 === 0) push('runner', Math.floor(w * 0.7), 0.3);
  if (w % 5 === 0) push('boss', w === 20 ? 2 : 1, 5);
  return list;
}
export function hpScale(w: number): number {
  const k = w - 1;
  return 1 + 0.17 * k + 0.014 * k * k;
}

import * as THREE from 'three';
import { ENEMIES, EnemyDef, EnemyKind, hpScale } from './config';
import type { Board } from './board';
import type { Particles } from './fx';
export interface Enemy {
  id: number;
  def: EnemyDef;
  hp: number;
  maxHp: number;
  dist: number;
  slowT: number;
  slowK: number;
  flash: number;
  healCd: number;
  alive: boolean;
  pos: THREE.Vector3;
  group: THREE.Group;
  mats: THREE.MeshStandardMaterial[];
  wings: THREE.Mesh[];
  hpFg: THREE.Sprite;
  hpBg: THREE.Sprite;
  barW: number;
}
export interface EnemyEvents {
  onKill(e: Enemy): void;
  onLeak(e: Enemy): void;
}
const GREEN = new THREE.Color(0x4ade80);
const ICE = new THREE.Color(0x60a5fa);
const WHITE = new THREE.Color(0xffffff);
export class EnemyManager {
  list: Enemy[] = [];
  private nextId = 1;
  private geos: Record<string, THREE.BufferGeometry> = {};
  private baseMats: Partial<Record<EnemyKind, THREE.MeshStandardMaterial>> = {};
  private eyeMat = new THREE.MeshBasicMaterial({ color: 0xfff7a1 });
  private haloMat = new THREE.MeshBasicMaterial({ color: 0x86efac, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending, depthWrite: false });
  private hpBgMat = new THREE.SpriteMaterial({ color: 0x111827, depthTest: false, transparent: true, opacity: 0.8 });
  private tmp = new THREE.Vector3();
  private tmp2 = new THREE.Vector3();
  constructor(private scene: THREE.Scene, private board: Board, private fx: Particles, private ev: EnemyEvents) {
    this.geos.dodeca = new THREE.DodecahedronGeometry(0.6, 0);
    this.geos.cone = new THREE.ConeGeometry(0.42, 1.2, 6);
    this.geos.box = new THREE.BoxGeometry(1.3, 0.75, 1.6);
    this.geos.turret = new THREE.CylinderGeometry(0.35, 0.45, 0.45, 8);
    this.geos.octa = new THREE.OctahedronGeometry(0.55, 0);
    this.geos.wing = new THREE.BoxGeometry(1.1, 0.04, 0.5);
    this.geos.ico = new THREE.IcosahedronGeometry(0.6, 0);
    this.geos.torus = new THREE.TorusGeometry(0.7, 0.06, 6, 24);
    this.geos.spike = new THREE.ConeGeometry(0.18, 0.7, 5);
    this.geos.eye = new THREE.SphereGeometry(0.1, 6, 6);
    for (const k of Object.keys(ENEMIES) as EnemyKind[]) {
      const d = ENEMIES[k];
      this.baseMats[k] = new THREE.MeshStandardMaterial({ color: d.color, emissive: d.emissive, emissiveIntensity: 0.6, roughness: 0.45, metalness: 0.25, flatShading: true });
    }
  }
  private mesh(geo: string, mat: THREE.Material, parent: THREE.Object3D) {
    const m = new THREE.Mesh(this.geos[geo], mat);
    m.castShadow = true; parent.add(m); return m;
  }
  spawn(kind: EnemyKind, wave: number, hpMul: number) {
    const def = ENEMIES[kind];
    const g = new THREE.Group();
    const body = new THREE.Group(); body.name = 'body'; g.add(body);
    const mat = this.baseMats[kind]!.clone();
    const mats = [mat];
    const wings: THREE.Mesh[] = [];
    switch (kind) {
      case 'grunt': {
        const b = this.mesh('dodeca', mat, body); b.position.y = 0.6;
        for (const s of [-1, 1]) { const e = this.mesh('eye', this.eyeMat, body); e.position.set(s * 0.22, 0.75, 0.48); }
        break;
      }
      case 'runner': {
        const b = this.mesh('cone', mat, body); b.rotation.x = Math.PI / 2; b.position.y = 0.55;
        const e = this.mesh('eye', this.eyeMat, body); e.position.set(0, 0.7, 0.4);
        break;
      }
      case 'tank': {
        const b = this.mesh('box', mat, body); b.position.y = 0.5;
        const t = this.mesh('turret', mat, body); t.position.y = 1.05;
        const e = this.mesh('eye', this.eyeMat, body); e.position.set(0, 1.05, 0.42); e.scale.setScalar(1.4);
        break;
      }
      case 'flyer': {
        const b = this.mesh('octa', mat, body); b.scale.set(1, 0.7, 1.4);
        for (const s of [-1, 1]) {
          const wm = new THREE.MeshStandardMaterial({ color: 0xe9d5ff, emissive: 0x9333ea, emissiveIntensity: 0.8, transparent: true, opacity: 0.8, side: THREE.DoubleSide });
          mats.push(wm);
          const w = this.mesh('wing', wm, body); w.position.set(s * 0.65, 0.1, 0); w.userData.side = s; wings.push(w);
        }
        break;
      }
      case 'healer': {
        const b = this.mesh('ico', mat, body); b.position.y = 0.7;
        const h = new THREE.Mesh(this.geos.torus, this.haloMat); h.rotation.x = Math.PI / 2; h.position.y = 1.45; body.add(h);
        break;
      }
      case 'boss': {
        const b = this.mesh('ico', mat, body); b.position.y = 0.85; b.scale.setScalar(1.3);
        for (let i = 0; i < 8; i++) {
          const s = this.mesh('spike', mat, body); const a = (i / 8) * Math.PI * 2;
          s.position.set(Math.cos(a) * 0.75, 0.9 + (i % 2) * 0.3, Math.sin(a) * 0.75);
          s.lookAt(Math.cos(a) * 3, 1.5 + (i % 2), Math.sin(a) * 3); s.rotateX(Math.PI / 2);
        }
        for (const s of [-1, 1]) { const e = this.mesh('eye', this.eyeMat, body); e.position.set(s * 0.3, 1.1, 0.72); e.scale.setScalar(1.6); }
        const crown = new THREE.Mesh(this.geos.torus, mat); crown.rotation.x = Math.PI / 2; crown.position.y = 1.75; crown.scale.setScalar(0.6); body.add(crown);
        break;
      }
    }
    g.scale.setScalar(def.scale);
    const barW = kind === 'boss' ? 1.6 : 1.0;
    const hpBg = new THREE.Sprite(this.hpBgMat); hpBg.scale.set(barW + 0.08, 0.16, 1); hpBg.renderOrder = 10;
    const hpFg = new THREE.Sprite(new THREE.SpriteMaterial({ color: 0x4ade80, depthTest: false, transparent: true }));
    hpFg.center.set(0, 0.5); hpFg.scale.set(barW, 0.1, 1); hpFg.renderOrder = 11;
    this.scene.add(g, hpBg, hpFg);
    const maxHp = Math.round(def.hp * hpScale(wave) * hpMul);
    const e: Enemy = {
      id: this.nextId++, def, hp: maxHp, maxHp, dist: -Math.random() * 0.5, slowT: 0, slowK: 0, flash: 0, healCd: 1,
      alive: true, pos: new THREE.Vector3(), group: g, mats, wings, hpFg, hpBg, barW,
    };
    this.board.sample(0, e.pos);
    g.position.copy(e.pos);
    this.list.push(e);
    return e;
  }
  /** Aplica daño; devuelve true si lo mata. */
  damage(e: Enemy, amount: number, pierce = false) {
    if (!e.alive) return false;
    const dmg = pierce ? amount : Math.max(amount * 0.25, amount - e.def.armor);
    e.hp -= dmg; e.flash = 0.12;
    if (e.hp <= 0) { this.kill(e); return true; }
    return false;
  }
  slow(e: Enemy, k: number, t: number) {
    if (k >= e.slowK || e.slowT <= 0) e.slowK = k;
    e.slowT = Math.max(e.slowT, t);
  }
  private kill(e: Enemy) {
    e.alive = false;
    this.ev.onKill(e);
    this.remove(e);
  }
  private remove(e: Enemy) {
    e.alive = false;
    this.scene.remove(e.group, e.hpBg, e.hpFg);
    e.mats.forEach(m => m.dispose());
    e.hpFg.material.dispose();
  }
  update(dt: number, t: number, camera: THREE.Camera) {
    for (const e of this.list) {
      if (!e.alive) continue;
      if (e.slowT > 0) { e.slowT -= dt; if (e.slowT <= 0) e.slowK = 0; }
      const spd = e.def.speed * (1 - e.slowK);
      e.dist += spd * dt;
      if (e.dist >= this.board.totalLen) { this.ev.onLeak(e); this.remove(e); continue; }
      this.board.sample(e.dist, e.pos);
      this.board.sample(e.dist + 0.6, this.tmp);
      const fy = e.def.flying ? 2.2 + Math.sin(t * 4 + e.id) * 0.25 : Math.abs(Math.sin(t * spd * 3 + e.id)) * 0.12;
      e.pos.y = fy;
      e.group.position.copy(e.pos);
      const dx = this.tmp.x - e.pos.x, dz = this.tmp.z - e.pos.z;
      if (dx * dx + dz * dz > 1e-4) {
        const target = Math.atan2(dx, dz);
        let diff = target - e.group.rotation.y;
        while (diff > Math.PI) diff -= Math.PI * 2; while (diff < -Math.PI) diff += Math.PI * 2;
        e.group.rotation.y += diff * Math.min(1, dt * 10);
      }
      const body = e.group.children[0];
      if (e.def.kind === 'grunt' || e.def.kind === 'healer') body.rotation.z = Math.sin(t * 8 + e.id) * 0.15;
      if (e.def.kind === 'boss') body.rotation.y = Math.sin(t * 1.5) * 0.3;
      e.wings.forEach(w => { w.rotation.z = Math.sin(t * 22 + e.id) * 0.6 * (w.userData.side as number); });
      // Color: destello de impacto / congelado
      e.flash = Math.max(0, e.flash - dt);
      const m0 = e.mats[0];
      m0.emissive.setHex(e.def.emissive);
      if (e.slowT > 0) m0.emissive.lerp(ICE, 0.75);
      if (e.flash > 0) m0.emissive.lerp(WHITE, e.flash / 0.12);
      m0.emissiveIntensity = e.flash > 0 ? 1.4 : e.def.kind === 'boss' ? 0.8 + Math.sin(t * 6) * 0.3 : 0.6;
      // Chamán: cura a los cercanos
      if (e.def.kind === 'healer') {
        e.healCd -= dt;
        if (e.healCd <= 0) {
          e.healCd = 1.2;
          for (const o of this.list) {
            if (!o.alive || o === e || o.hp >= o.maxHp) continue;
            if (o.pos.distanceToSquared(e.pos) < 3.4 * 3.4) {
              o.hp = Math.min(o.maxHp, o.hp + o.maxHp * 0.08);
              this.fx.emit(o.pos.x, o.pos.y + 1, o.pos.z, GREEN, { n: 4, speed: 1, size: 0.4, up: 2, gravity: -1 });
            }
          }
          this.fx.emit(e.pos.x, 1.2, e.pos.z, GREEN, { n: 8, speed: 3, size: 0.45, up: 0.5, gravity: 0 });
        }
      }
      // Barra de vida
      const ratio = Math.max(0, e.hp / e.maxHp);
      const show = ratio < 0.999 || e.def.kind === 'boss';
      e.hpBg.visible = e.hpFg.visible = show;
      if (show) {
        const top = e.pos.y + 1.5 * e.def.scale + 0.4;
        e.hpBg.position.set(e.pos.x, top, e.pos.z);
        this.tmp2.set(1, 0, 0).applyQuaternion(camera.quaternion).multiplyScalar(-e.barW / 2);
        e.hpFg.position.set(e.pos.x + this.tmp2.x, top + this.tmp2.y, e.pos.z + this.tmp2.z);
        e.hpFg.scale.x = Math.max(0.001, e.barW * ratio);
        (e.hpFg.material as THREE.SpriteMaterial).color.setHSL(ratio * 0.33, 0.85, 0.55);
      }
    }
    this.list = this.list.filter(e => e.alive);
  }
  /** El enemigo más avanzado dentro del radio. */
  firstInRange(x: number, z: number, range: number, air: boolean, ground: boolean): Enemy | null {
    let best: Enemy | null = null;
    const r2 = range * range;
    for (const e of this.list) {
      if (!e.alive) continue;
      if (e.def.flying ? !air : !ground) continue;
      const dx = e.pos.x - x, dz = e.pos.z - z;
      if (dx * dx + dz * dz <= r2 && (!best || e.dist > best.dist)) best = e;
    }
    return best;
  }
  inRadius(x: number, z: number, r: number, air: boolean, ground: boolean): Enemy[] {
    const r2 = r * r;
    return this.list.filter(e => e.alive && (e.def.flying ? air : ground) && (e.pos.x - x) ** 2 + (e.pos.z - z) ** 2 <= r2);
  }
  clear() { [...this.list].forEach(e => this.remove(e)); this.list = []; }
  dispose() {
    this.clear();
    Object.values(this.geos).forEach(g => g.dispose());
    Object.values(this.baseMats).forEach(m => m && m.dispose());
    this.eyeMat.dispose(); this.haloMat.dispose(); this.hpBgMat.dispose();
  }
}

