    const n = opts.n ?? 10, sp = opts.speed ?? 4, sz = opts.size ?? 0.5, lf = opts.life ?? 0.7;
    for (let k = 0; k < n; k++) {
      const i = this.cursor; this.cursor = (this.cursor + 1) % MAX_P;
      const th = Math.random() * Math.PI * 2, ph = Math.random() * Math.PI - Math.PI / 2;
      const s = sp * (0.35 + Math.random() * 0.65);
      const sprd = opts.spread ?? 0;
      this.pos[i * 3] = x + (Math.random() - 0.5) * sprd; this.pos[i * 3 + 1] = y; this.pos[i * 3 + 2] = z + (Math.random() - 0.5) * sprd;
      this.vel[i * 3] = Math.cos(th) * Math.cos(ph) * s;
      this.vel[i * 3 + 1] = Math.abs(Math.sin(ph)) * s + (opts.up ?? 1.5);
      this.vel[i * 3 + 2] = Math.sin(th) * Math.cos(ph) * s;
      const v = 0.8 + Math.random() * 0.4;
      this.col[i * 3] = color.r * v; this.col[i * 3 + 1] = color.g * v; this.col[i * 3 + 2] = color.b * v;
      this.maxLife[i] = this.life[i] = lf * (0.6 + Math.random() * 0.6);
      this.baseSize[i] = sz * (0.6 + Math.random() * 0.8);
      this.grav[i] = opts.gravity ?? 6;
    }
  }
  update(dt: number) {
    for (let i = 0; i < MAX_P; i++) {
      if (this.life[i] <= 0) { this.alpha[i] = 0; this.size[i] = 0; continue; }
      this.life[i] -= dt;
