export class Shockwaves {
  private pool: Ring[] = [];
  private geo = new THREE.RingGeometry(0.82, 1, 48);
  constructor(scene: THREE.Scene) {
    for (let i = 0; i < 24; i++) {
      const mat = new THREE.MeshBasicMaterial({ transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
      const mesh = new THREE.Mesh(this.geo, mat);
      mesh.rotation.x = -Math.PI / 2; mesh.visible = false;
      scene.add(mesh);
      this.pool.push({ mesh, mat, t: 0, dur: 0, from: 0, to: 0 });
    }
  }
  spawn(x: number, y: number, z: number, color: THREE.Color | number, from: number, to: number, dur = 0.5) {
    const r = this.pool.find(p => !p.mesh.visible) || this.pool[0];
    r.mesh.position.set(x, y, z); r.mesh.visible = true;
    r.mat.color.set(color); r.t = 0; r.dur = dur; r.from = from; r.to = to;
  }
  update(dt: number) {
    for (const r of this.pool) {
      if (!r.mesh.visible) continue;
      r.t += dt;
      const k = r.t / r.dur;
      if (k >= 1) { r.mesh.visible = false; continue; }
      const s = r.from + (r.to - r.from) * (1 - (1 - k) * (1 - k));
      r.mesh.scale.set(s, s, s);
      r.mat.opacity = 1 - k;
    }
  }
  dispose() { this.geo.dispose(); this.pool.forEach(p => p.mat.dispose()); }
}
/** Crea una textura de brillo radial para sprites. */
export function glowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)'): THREE.CanvasTexture {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d')!;
  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grd.addColorStop(0, inner); grd.addColorStop(0.25, inner.replace(/[\d.]+\)$/, '0.6)')); grd.addColorStop(1, outer);
  g.fillStyle = grd; g.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}

import * as THREE from 'three';
// Mismo flujo de color en r128 y r170: los hex se usan tal cual (modo clásico de r128)
const CM = (THREE as any).ColorManagement;
if (CM && 'enabled' in CM) CM.enabled = false;
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1; // multiplica TODAS las intensidades de luz
export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}
export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding; return t;
}

import * as THREE from 'three';
import { TOWERS, TowerDef, TowerKind, tileToWorld } from './config';
import type { Board } from './board';
import type { EnemyManager, Enemy } from './enemies';
import type { Particles, Shockwaves } from './fx';
import { glowTexture } from './fx';
import { sfx } from './audio';
export interface Tower {
  def: TowerDef;
  level: number;
  c: number; r: number; x: number; z: number;
  group: THREE.Group;
  head: THREE.Group;
  muzzle: THREE.Object3D;
  orbs: THREE.Mesh[];
  cd: number;
  recoil: number;
  spent: number;
  beam: THREE.Mesh | null;
  beamGlow: THREE.Sprite | null;
}
interface Ball { mesh: THREE.Mesh; from: THREE.Vector3; to: THREE.Vector3; t: number; dur: number; dmg: number; splash: number; active: boolean; }
interface Missile { mesh: THREE.Mesh; vel: THREE.Vector3; target: Enemy | null; last: THREE.Vector3; dmg: number; splash: number; life: number; active: boolean; }
const C_ORANGE = new THREE.Color(0xfb923c);
const C_FIRE = new THREE.Color(0xfde047);
const C_PINK = new THREE.Color(0xf472b6);
const C_ICE = new THREE.Color(0xa5f3fc);
const C_LIME = new THREE.Color(0xbef264);
const C_SMOKE = new THREE.Color(0x6b7280);
export class TowerManager {
  list: Tower[] = [];
  private g: Record<string, THREE.BufferGeometry> = {};
  private m: Record<string, THREE.Material> = {};
  private balls: Ball[] = [];
