  constructor(private scene: THREE.Scene, private board: Board, private enemies: EnemyManager,
    private fx: Particles, private waves: Shockwaves, private shake: (a: number) => void) {
    const g = this.g, m = this.m;
    g.base = new THREE.CylinderGeometry(0.85, 1.0, 0.55, 6);
    g.band = new THREE.CylinderGeometry(0.88, 0.88, 0.1, 6);
    g.orb = new THREE.SphereGeometry(0.11, 8, 8);
    g.sphere = new THREE.SphereGeometry(0.55, 16, 12);
    g.barrel = new THREE.CylinderGeometry(0.15, 0.2, 1.1, 10);
    g.pillar = new THREE.CylinderGeometry(0.22, 0.42, 1.8, 8);
    g.crystal = new THREE.OctahedronGeometry(0.42, 0);
    g.icicle = new THREE.ConeGeometry(0.22, 1.3, 5);
    g.launcher = new THREE.BoxGeometry(1.0, 0.5, 0.8);
    g.tube = new THREE.CylinderGeometry(0.12, 0.12, 0.8, 8);
    g.ball = new THREE.SphereGeometry(0.22, 10, 8);
    g.missile = new THREE.ConeGeometry(0.12, 0.55, 6);
    g.beam = new THREE.CylinderGeometry(0.1, 0.1, 1, 6, 1, true);
    g.beam.translate(0, 0.5, 0); g.beam.rotateX(Math.PI / 2);
    m.stone = new THREE.MeshStandardMaterial({ color: 0x3a3448, roughness: 0.8, flatShading: true });
    m.metal = new THREE.MeshStandardMaterial({ color: 0x15171f, roughness: 0.35, metalness: 0.7 });
    m.orb = new THREE.MeshBasicMaterial({ color: 0xfde68a });
    m.ball = new THREE.MeshBasicMaterial({ color: 0x1f2937 });
    m.missile = new THREE.MeshStandardMaterial({ color: 0xe5e7eb, emissive: 0x65a30d, emissiveIntensity: 0.6 });
    m.beam = new THREE.MeshBasicMaterial({ color: 0xff1fa8, transparent: true, opacity: 0.85, depthWrite: false });
    for (const k of Object.keys(TOWERS) as TowerKind[]) {
      const col = new THREE.Color(TOWERS[k].color);
      m['acc_' + k] = new THREE.MeshStandardMaterial({ color: col, emissive: col, emissiveIntensity: 0.9, roughness: 0.3, flatShading: true });
    }
  }
  private mk(geo: string, mat: string, parent: THREE.Object3D, shadow = true) {
    const mesh = new THREE.Mesh(this.g[geo], this.m[mat]);
    mesh.castShadow = shadow; parent.add(mesh); return mesh;
  }
  at(c: number, r: number) { return this.list.find(t => t.c === c && t.r === r) || null; }
  build(kind: TowerKind, c: number, r: number, free = false): Tower {
    const def = TOWERS[kind];
    const w = tileToWorld(c, r);
    const group = new THREE.Group(); group.position.set(w.x, 0, w.z);
    const base = this.mk('base', 'stone', group); base.position.y = 0.27; base.receiveShadow = true;
    const band = this.mk('band', 'acc_' + kind, group, false); band.position.y = 0.5;
    const head = new THREE.Group(); head.position.y = 0.6; group.add(head);
    const muzzle = new THREE.Object3D(); head.add(muzzle);
    const acc = 'acc_' + kind;
    let beam: THREE.Mesh | null = null, beamGlow: THREE.Sprite | null = null;
    if (kind === 'cannon') {
      const s = this.mk('sphere', 'metal', head); s.position.y = 0.4;
      const b = this.mk('barrel', 'metal', head); b.rotation.x = Math.PI / 2; b.position.set(0, 0.5, 0.55); b.name = 'barrel';
      const r = this.mk('band', acc, head, false); r.scale.set(0.25, 1, 0.25); r.rotation.x = Math.PI / 2; r.position.set(0, 0.5, 1.08);
      muzzle.position.set(0, 0.5, 1.15);
    } else if (kind === 'laser') {
      const p = this.mk('pillar', 'stone', head); p.position.y = 0.9;
      const cr = this.mk('crystal', acc, head); cr.position.y = 2.25; cr.scale.set(0.9, 1.5, 0.9); cr.name = 'crystal';
      muzzle.position.set(0, 2.25, 0);
      beam = new THREE.Mesh(this.g.beam, this.m.beam); beam.visible = false; this.scene.add(beam);
      beamGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: 0xff7ad9, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
      beamGlow.scale.set(1.6, 1.6, 1); beamGlow.visible = false; this.scene.add(beamGlow);
    } else if (kind === 'ice') {
      for (let i = 0; i < 5; i++) {
        const ic = this.mk('icicle', acc, head); const a = (i / 5) * Math.PI * 2;
        const rr = i === 0 ? 0 : 0.38;
        ic.position.set(Math.cos(a) * rr, 0.6 + (i === 0 ? 0.35 : 0), Math.sin(a) * rr);
        ic.rotation.set(Math.sin(a) * 0.35 * (i ? 1 : 0), 0, -Math.cos(a) * 0.35 * (i ? 1 : 0));
        if (i === 0) ic.scale.set(1.3, 1.4, 1.3);
      }
      muzzle.position.set(0, 1.2, 0);
    } else {
      const l = this.mk('launcher', 'metal', head); l.position.y = 0.45;
      for (let i = 0; i < 4; i++) {
        const t = this.mk('tube', acc, head); t.rotation.x = Math.PI / 2 - 0.25;
        t.position.set((i % 2 ? 0.22 : -0.22), 0.55 + (i < 2 ? 0.14 : -0.1), 0.25);
      }
      muzzle.position.set(0, 0.7, 0.6);
    }
    this.scene.add(group);
    const tw: Tower = { def, level: 0, c, r, x: w.x, z: w.z, group, head, muzzle, orbs: [], cd: Math.random() * 0.5, recoil: 0, spent: free ? Math.round(def.levels[0].cost * 0.6) : def.levels[0].cost, beam, beamGlow };
    this.refreshLevel(tw);
    this.list.push(tw);
    this.waves.spawn(w.x, 0.1, w.z, new THREE.Color(def.color), 0.3, 1.8, 0.6);
    this.fx.emit(w.x, 0.6, w.z, new THREE.Color(def.color), { n: 18, speed: 4, size: 0.45, up: 2 });
    return tw;
  }
  private refreshLevel(t: Tower) {
    t.orbs.forEach(o => t.group.remove(o)); t.orbs = [];
    for (let i = 0; i <= t.level; i++) {
      const o = this.mk('orb', 'orb', t.group, false);
      const a = (i / 3) * Math.PI * 2 + Math.PI / 6;
      o.position.set(Math.cos(a) * 0.92, 0.5, Math.sin(a) * 0.92);
      t.orbs.push(o);
    }
    t.head.scale.setScalar(1 + t.level * 0.14);
  }
  upgrade(t: Tower) {
    if (t.level >= t.def.levels.length - 1) return;
    t.level++; t.spent += t.def.levels[t.level].cost;
    this.refreshLevel(t);
    this.waves.spawn(t.x, 0.1, t.z, 0xfde68a, 0.4, 2.4, 0.7);
    this.fx.emit(t.x, 1.2, t.z, new THREE.Color(0xfde68a), { n: 26, speed: 5, size: 0.5, up: 4 });
  }
  sell(t: Tower): number {
    const refund = Math.round(t.spent * 0.7);
    this.scene.remove(t.group);
    if (t.beam) this.scene.remove(t.beam);
    if (t.beamGlow) { this.scene.remove(t.beamGlow); t.beamGlow.material.dispose(); }
    this.list = this.list.filter(x => x !== t);
    this.fx.emit(t.x, 0.8, t.z, new THREE.Color(0xfacc15), { n: 20, speed: 4, size: 0.45, up: 3 });
    return refund;
  }
  private aim(t: Tower, e: Enemy, dt: number) {
    const target = Math.atan2(e.pos.x - t.x, e.pos.z - t.z);
    let d = target - t.head.rotation.y;
    while (d > Math.PI) d -= Math.PI * 2; while (d < -Math.PI) d += Math.PI * 2;
    t.head.rotation.y += d * Math.min(1, dt * 12);
  }
  private explode(x: number, y: number, z: number, dmg: number, radius: number, air: boolean, color: THREE.Color) {
    for (const e of this.enemies.inRadius(x, z, radius, air, true)) {
      const k = 1 - 0.5 * Math.sqrt((e.pos.x - x) ** 2 + (e.pos.z - z) ** 2) / radius;
      this.enemies.damage(e, dmg * k);
    }
    this.fx.emit(x, y + 0.2, z, color, { n: 22, speed: 6, size: 0.7, up: 3 });
    this.fx.emit(x, y + 0.2, z, C_FIRE, { n: 8, speed: 2, size: 1.1, up: 1.5, life: 0.4 });
    this.fx.emit(x, y + 0.3, z, C_SMOKE, { n: 6, speed: 1.2, size: 1.2, up: 1.6, gravity: -0.8, life: 1.1 });
    this.waves.spawn(x, 0.12, z, color, 0.2, radius * 1.1, 0.45);
    sfx.explode();
    this.shake(0.12);
  }
  update(dt: number, t: number) {
    for (const tw of this.list) {
      const L = tw.def.levels[tw.level];
      tw.cd -= dt;
      tw.recoil = Math.max(0, tw.recoil - dt * 4);
      const e = this.enemies.firstInRange(tw.x, tw.z, L.range, tw.def.hitsAir, tw.def.hitsGround);
      const kind = tw.def.kind;
      if (kind === 'ice') {
        tw.head.rotation.y += dt * 0.6;
        if (e && tw.cd <= 0) {
          tw.cd = 1 / L.rate;
          for (const o of this.enemies.inRadius(tw.x, tw.z, L.range, true, true)) {
            this.enemies.slow(o, tw.def.slow[tw.level], 1.8);
            this.enemies.damage(o, L.dmg, true);
          }
          this.waves.spawn(tw.x, 0.15, tw.z, 0x67e8f9, 0.5, L.range, 0.55);
          this.fx.emit(tw.x, 1.4, tw.z, C_ICE, { n: 16, speed: 5, size: 0.4, up: 1, gravity: 2, spread: 1 });
          tw.recoil = 1; sfx.ice();
        }
        tw.head.position.y = 0.6 + tw.recoil * 0.15;
        continue;
      }
      if (kind === 'laser') {
        const crystal = tw.head.getObjectByName('crystal');
        if (crystal) { crystal.rotation.y = t * 2; crystal.position.y = 2.25 + Math.sin(t * 3 + tw.x) * 0.1; }
        if (e && tw.beam && tw.beamGlow) {
          tw.muzzle.getWorldPosition(this.v);
          this.v2.set(e.pos.x, e.pos.y + 0.6 * e.def.scale, e.pos.z);
          const len = this.v.distanceTo(this.v2);
          tw.beam.position.copy(this.v); tw.beam.lookAt(this.v2);
          const w = 1 + tw.level * 0.6 + Math.sin(t * 40) * 0.25;
          tw.beam.scale.set(w, w, len); tw.beam.visible = true;
          tw.beamGlow.position.copy(this.v2); tw.beamGlow.visible = true;
          tw.beamGlow.scale.setScalar(1.3 + Math.sin(t * 30) * 0.3 + tw.level * 0.3);
          this.enemies.damage(e, L.dmg * dt, false);
          if (Math.random() < dt * 25) this.fx.emit(this.v2.x, this.v2.y, this.v2.z, C_PINK, { n: 2, speed: 4, size: 0.35, life: 0.35 });
          sfx.laser();
        } else if (tw.beam && tw.beamGlow) { tw.beam.visible = false; tw.beamGlow.visible = false; }
        continue;
      }
      if (!e) continue;
      this.aim(tw, e, dt);
      const barrel = tw.head.getObjectByName('barrel');
      if (barrel) barrel.position.z = 0.55 - tw.recoil * 0.25;
      if (tw.cd > 0) continue;
      tw.cd = 1 / L.rate;
      tw.recoil = 1;
      tw.muzzle.getWorldPosition(this.v);
      if (kind === 'cannon') {
        const dur = 0.6;
        const ahead = e.def.speed * (1 - e.slowK) * dur;
        const to = this.board.sample(e.dist + ahead, new THREE.Vector3());
        const b = this.balls.find(x => !x.active) || this.newBall();
        b.from.copy(this.v); b.to.copy(to); b.t = 0; b.dur = dur; b.dmg = L.dmg; b.splash = tw.def.splash; b.active = true; b.mesh.visible = true;
        this.fx.emit(this.v.x, this.v.y, this.v.z, C_ORANGE, { n: 8, speed: 3, size: 0.5, life: 0.3, up: 1 });
        sfx.cannon();
      } else {
        const mi = this.missiles.find(x => !x.active) || this.newMissile();
        mi.mesh.position.copy(this.v); mi.vel.set(Math.sin(tw.head.rotation.y) * 3, 7, Math.cos(tw.head.rotation.y) * 3);
        mi.target = e; mi.last.copy(e.pos); mi.dmg = L.dmg; mi.splash = tw.def.splash; mi.life = 4; mi.active = true; mi.mesh.visible = true;
        sfx.missile();
      }
    }
    this.updateProjectiles(dt);
  }
  private newBall(): Ball {
    const mesh = new THREE.Mesh(this.g.ball, this.m.ball); mesh.castShadow = true; this.scene.add(mesh);
    const b: Ball = { mesh, from: new THREE.Vector3(), to: new THREE.Vector3(), t: 0, dur: 1, dmg: 0, splash: 0, active: false };
    this.balls.push(b); return b;
  }
  private newMissile(): Missile {
    const mesh = new THREE.Mesh(this.g.missile, this.m.missile); this.scene.add(mesh);
    const mi: Missile = { mesh, vel: new THREE.Vector3(), target: null, last: new THREE.Vector3(), dmg: 0, splash: 0, life: 0, active: false };
    this.missiles.push(mi); return mi;
  }
  private updateProjectiles(dt: number) {
    for (const b of this.balls) {
      if (!b.active) continue;
      b.t += dt;
      const k = Math.min(1, b.t / b.dur);
      b.mesh.position.lerpVectors(b.from, b.to, k);
      b.mesh.position.y += Math.sin(k * Math.PI) * 2.8;
      if (k >= 1) { b.active = false; b.mesh.visible = false; this.explode(b.to.x, 0.2, b.to.z, b.dmg, b.splash, false, C_ORANGE); }
    }
    for (const mi of this.missiles) {
      if (!mi.active) continue;
      mi.life -= dt;
      if (mi.target && mi.target.alive) mi.last.set(mi.target.pos.x, mi.target.pos.y + 0.5, mi.target.pos.z);
      this.v.copy(mi.last).sub(mi.mesh.position);
      const d = this.v.length();
      this.v.normalize().multiplyScalar(16);
      mi.vel.lerp(this.v, Math.min(1, dt * 4.5));
      mi.mesh.position.addScaledVector(mi.vel, dt);
      this.v2.copy(mi.mesh.position).add(mi.vel);
      mi.mesh.lookAt(this.v2); mi.mesh.rotateX(Math.PI / 2);
      if (Math.random() < 0.8) this.fx.emit(mi.mesh.position.x, mi.mesh.position.y, mi.mesh.position.z, Math.random() < 0.5 ? C_FIRE : C_SMOKE, { n: 1, speed: 0.5, size: 0.45, life: 0.45, up: 0.3, gravity: 0 });
      if (d < 0.7 || mi.life <= 0) {
        mi.active = false; mi.mesh.visible = false;
        this.explode(mi.mesh.position.x, Math.max(0.2, mi.mesh.position.y), mi.mesh.position.z, mi.dmg, mi.splash, true, C_LIME);
      }
    }
  }
  clear() { [...this.list].forEach(t => this.sell(t)); }
  dispose() {
    this.clear();
    this.balls.forEach(b => this.scene.remove(b.mesh));
    this.missiles.forEach(m => this.scene.remove(m.mesh));
    Object.values(this.g).forEach(g => g.dispose());
    Object.values(this.m).forEach(m => m.dispose());
    this.glowTex.dispose();
  }
}

.td-root { font-family: 'Trebuchet MS', 'Segoe UI', system-ui, sans-serif; }
.td-title { background: linear-gradient(180deg, #fef3c7 0%, #fbbf24 45%, #f472b6 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 4px 18px rgba(244, 114, 182, 0.45)); letter-spacing: -0.02em; }
.td-glass { background: rgba(15, 10, 35, 0.62); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border: 1px solid rgba(196, 181, 253, 0.22); }
.td-banner { animation: td-pop 0.35s cubic-bezier(.2, 1.6, .4, 1) both; text-shadow: 0 2px 0 rgba(0, 0, 0, 0.35), 0 0 24px rgba(251, 191, 36, 0.7); }
