}
.td-menu-bg { background: radial-gradient(ellipse at 70% 20%, rgba(244, 114, 182, 0.28), transparent 55%), radial-gradient(ellipse at 20% 80%, rgba(56, 189, 248, 0.22), transparent 50%), linear-gradient(180deg, #070a24 0%, #2b1650 60%, #6b2f5e 100%); }
